SLIDES=[]
def add(label,title,body,*,theme='',subtitle='',source='',notes=''):
    SLIDES.append(dict(label=label,title=title,body=body,theme=theme,subtitle=subtitle,source=source,notes=notes))
def tool(name,label):
    return f'<span class="tool"><img src="tool-logos/{name}.svg" alt=""><span>{label}</span></span>'
